// Copies the shared locale JSON from packages/i18n-locales/locales/ into
// public/i18n/ so Angular CLI's asset pipeline (which can't glob outside the
// workspace root) picks it up and serves it at /angular/i18n/<lang>.json.
// React reads the same source files directly via a Vite glob; this keeps
// Angular on the identical translation content without a second copy in git
// (public/i18n/ is gitignored and regenerated by this script).
import { cpSync, mkdirSync, readdirSync, rmSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const source = join(here, '..', '..', 'packages', 'i18n-locales', 'locales');
const dest = join(here, '..', 'public', 'i18n');

rmSync(dest, { recursive: true, force: true });
mkdirSync(dest, { recursive: true });

for (const file of readdirSync(source)) {
  if (file.endsWith('.json')) {
    cpSync(join(source, file), join(dest, file));
  }
}
